        assertEquals("FORMA_PAGAMENTO_INVALIDA", erro.getCodigo());
    }

    @Test
    void parcelamentoInvalido_PixComParcelas() {
        RequisicaoResumoDTO requisicao = new RequisicaoResumoDTO();
        requisicao.setItens(Arrays.asList(
